Definition glob_piv (r : Z * Z * Z) : Z * Z := let '(q, sz, kq) := r in (q + sz / 8, q + kq).
Definition tab_piv : Z * Z := (ATAB / 8, ATAB / 8 + 8 * ATAB_N).

(* [comment removed for export] *)
Definition glob_val (g : Z) (r : Z * Z * Z) : Z :=
  let '(q, sz, kq) := r in if (g =? q + sz / 8) && negb (sz mod 8 =? 0) then sz mod 8 else RZ.

Definition img_shval (g : Z) : Z :=
  if in_iv g tab_piv then RZ
  else match find (fun r => in_iv g (glob_piv r)) img_globs with
       | Some r => glob_val g r
       | None => 0
       end.

Definition img_shadow0 (g : Z) : bool := img_shval g =? 0.



