Definition img_pivs : list (Z * Z) := tab_piv :: map glob_piv img_globs.

(* [comment removed for export] *)
Fixpoint advance (cur : Z) (ivs : list (Z * Z)) : Z :=
  match ivs with
  | [] => cur
  | (lo, hi) :: ivs' => let r := advance cur ivs' in if (lo <=? cur) && (cur <? hi) then Z.max r hi else r
  end.



(* [comment removed for export] *)
Fixpoint covered (fuel : nat) (cur hi : Z) (ivs : list (Z * Z)) : bool :=
  if hi <=? cur then true
  else match fuel with
       | O => false
       | S f => let c' := advance cur ivs in if cur <? c' then covered f c' hi ivs else false
       end.


(* [comment removed for export] *)
Fixpoint runs_check (fuel : nat) (cur hi : Z) (runs pivs : list (Z * Z)) : bool :=
  match runs with
  | [] => covered fuel cur hi pivs
  | (c, d) :: runs' =>
      if (cur <=? c) && (c <=? d) && covered fuel cur c pivs then runs_check fuel d hi runs' pivs else false
  end.




