  #[using="Type"] Theorem aobj_img : forall CS m a n, img_cs CS -> img_shadow_ok m -> img_norz a n = true -> aobj segs AL CS m a n.
  Proof.
    intros CS m a n ICS ISH H.
    ddestruct (img_norz_sound a n H) as (N & LO & HI & G1 & G2 & BY).
    split; [apply ICS; assumption|].
    intros x Hx. specialize (BY x Hx).
    assert (Hg : IMG_GLO <= x / 8 < IMG_GHI).
    { unfold IMG_GLO, IMG_GHI, IMG_LO, IMG_HI in *. split; [apply Z.div_le_lower_bound|apply Z.div_lt_upper_bound]; lia. }
    assert (NR : img_shval (x / 8) <> RZ) by (unfold RZ; lia).
    exists (Z_to_bv 8 (img_shval (x / 8))). split.
    - rewrite shadow_of_granule. apply ISH; assumption.
    - unfold shadow_val_ok. rewrite Z_to_bv_unsigned.
      change (bv_wrap 8 (img_shval (x / 8))) with (img_shval (x / 8) mod 2 ^ 8).
      rewrite Z.mod_small by lia. lia.
  Qed.

